package creation;
/** A separate product type; its style must match the chosen heading. */
public interface BodyLine {
    Style style();
    String render(String text);
}

// Factory Method: subclasses choose a rendering product for a shared workflow.
package creation;
import java.util.Objects;

public final class Exporters {
    private Exporters() {}
    public abstract static class Exporter {
        protected abstract Renderer createRenderer();
        public final String export(Report report) {
            Objects.requireNonNull(report, "report");
            Renderer product = Objects.requireNonNull(createRenderer(), "renderer");
            return Objects.requireNonNull(product.render(report), "rendered text");
        }
    }
    public static final class Plain extends Exporter {
        protected Renderer createRenderer() { return RendererFactory.forStyle(Style.PLAIN); }
    }
    public static final class Boxed extends Exporter {
        protected Renderer createRenderer() { throw new UnsupportedOperationException("Implement the boxed exporter factory method."); }
    }
}

// Abstract Factory: create a compatible heading and body-line family.
package creation;
import java.util.Objects;

public final class Families {
    private Families() {}
    public interface Factory {
        Heading heading();
        BodyLine bodyLine();
    }
    public static final class PlainHeading implements Heading {
        public Style style() { return Style.PLAIN; }
        public String render(String title) { return Objects.requireNonNull(title, "title") + "\n"; }
    }
    public static final class PlainLine implements BodyLine {
        public Style style() { return Style.PLAIN; }
        public String render(String text) { return Objects.requireNonNull(text, "text") + "\n"; }
    }
    public static final class BoxedHeading implements Heading {
        public Style style() { return Style.BOXED; }
        public String render(String title) { return "[" + Objects.requireNonNull(title, "title") + "]\n"; }
    }
    public static final class BoxedLine implements BodyLine {
        public Style style() { return Style.BOXED; }
        public String render(String text) { return "| " + Objects.requireNonNull(text, "text") + " |\n"; }
    }
    public static final class PlainFactory implements Factory {
        public Heading heading() { return new PlainHeading(); }
        public BodyLine bodyLine() { return new PlainLine(); }
    }
    public static final class BoxedFactory implements Factory {
        public Heading heading() { throw new UnsupportedOperationException("Implement the boxed heading product."); }
        public BodyLine bodyLine() { throw new UnsupportedOperationException("Implement the boxed body-line product."); }
    }
}

package creation;
import java.util.Objects;

public final class FamilyRenderer implements Renderer {
    private final Heading heading;
    private final BodyLine bodyLine;
    private final Style style;
    public FamilyRenderer(Heading heading, BodyLine bodyLine) {
        this.heading = Objects.requireNonNull(heading, "heading");
        this.bodyLine = Objects.requireNonNull(bodyLine, "bodyLine");
        style = Objects.requireNonNull(heading.style(), "heading style");
        if (style != Objects.requireNonNull(bodyLine.style(), "body style"))
            throw new IllegalArgumentException("product families must match");
    }
    public Style style() { return style; }
    public String render(Report report) {
        Objects.requireNonNull(report, "report");
        StringBuilder text = new StringBuilder(Objects.requireNonNull(heading.render(report.title()), "heading text"));
        for (String line : report.lines()) text.append(Objects.requireNonNull(bodyLine.render(line), "body text"));
        return text.toString();
    }
}

package creation;
/** Products have stable non-null style metadata and accept non-null text. */
public interface Heading {
    Style style();
    String render(String title);
}

package creation;
public interface Renderer {
    Style style();
    String render(Report report);
}

package creation;
import java.util.Objects;

/** A fixed enum choice is a simple static factory, not the Factory Method pattern. */
public final class RendererFactory {
    private RendererFactory() {}
    public static Renderer from(Families.Factory family) {
        Objects.requireNonNull(family, "family");
        return new FamilyRenderer(family.heading(), family.bodyLine());
    }
    public static Renderer forStyle(Style style) {
        Objects.requireNonNull(style, "style");
        return from(switch (style) {
            case PLAIN -> new Families.PlainFactory();
            case BOXED -> new Families.BoxedFactory();
        });
    }
}

package creation;
import java.util.List;
import java.util.Objects;

/** Immutable single-line title and snapshot of immutable body strings. */
public record Report(String title, List<String> lines) {
    public Report {
        Objects.requireNonNull(title, "title");
        Objects.requireNonNull(lines, "lines");
        if (title.isBlank() || title.contains("\n") || title.contains("\r"))
            throw new IllegalArgumentException("title must be a nonblank single line");
        for (String line : lines) {
            Objects.requireNonNull(line, "line");
            if (line.contains("\n") || line.contains("\r"))
                throw new IllegalArgumentException("each body item must be a single line");
        }
        lines = List.copyOf(lines);
    }
}

// Builder: named options become an immutable job snapshot.
package creation;
import java.util.Objects;

public record ReportJob(Report report, Style style, boolean includeCount, String footer) {
    public ReportJob {
        Objects.requireNonNull(report, "report");
        Objects.requireNonNull(style, "style");
        footer = validFooter(footer);
    }
    private static String validFooter(String value) {
        Objects.requireNonNull(value, "footer");
        if (value.contains("\n") || value.contains("\r"))
            throw new IllegalArgumentException("footer must be one line");
        return value;
    }
    public String render() {
        String text = RendererFactory.forStyle(style).render(report);
        if (includeCount) text += "Lines: " + report.lines().size() + "\n";
        if (!footer.isEmpty()) text += footer + "\n";
        return text;
    }
    public Builder toBuilder() {
        throw new UnsupportedOperationException("Implement the optional independent toBuilder copy.");
    }
    public static final class Builder {
        private final Report report;
        private Style style = Style.PLAIN;
        private boolean includeCount;
        private String footer = "";
        public Builder(Report report) { this.report = Objects.requireNonNull(report, "report"); }
        public Builder style(Style value) {
            throw new UnsupportedOperationException("Implement the style option.");
        }
        public Builder includeCount(boolean value) {
            throw new UnsupportedOperationException("Implement the count option.");
        }
        public Builder footer(String value) {
            throw new UnsupportedOperationException("Implement the footer option.");
        }
        public ReportJob build() { throw new UnsupportedOperationException("Build an immutable report job snapshot."); }
    }
}
